def prompt(title, text, pid):
    return f'''<div class="prompt"><div class="ph"><b>{h.escape(title)}</b><button data-copy="{pid}">Скопировать</button></div><textarea id="{pid}" readonly>{h.escape(text)}</textarea></div>'''

